const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) { throw new Error('N8N_WEBHOOK_SECRET is not set'); }
const item = $input.first();
const headers = (item.json && item.json.headers) || {};
const ts = headers['x-lit-timestamp'];
const eventId = headers['x-lit-event-id'];
const signature = headers['x-lit-signature'];
if (!ts || !eventId || !signature) { throw new Error('Missing signing headers'); }
const body = (item.json && item.json.body) !== undefined ? item.json.body : {};
const rawBody = typeof body === 'string' ? body : JSON.stringify(body);
const mac = crypto.createHmac('sha256', secret).update(ts + '.' + eventId + '.' + rawBody).digest('hex');
const expected = 'v1=' + mac;
const a = Buffer.from(expected);
const b = Buffer.from(String(signature));
const matches = a.length === b.length && crypto.timingSafeEqual(a, b);
if (!matches) { throw new Error('Signature verification failed'); }
const nowSec = Math.floor(Date.now() / 1000);
if (Math.abs(nowSec - Number(ts)) > 300) { throw new Error('Signature timestamp outside tolerance'); }
return [{ json: { verified: true, eventId, timestamp: ts, body } }];

const item = $input.first().json;
const payload = (item.body && item.body.payload) ? item.body.payload : (item.body || {});

const projectId = String(payload.projectId || payload.project_id || 'PROJ-DEFAULT').trim();
const milestoneNumber = Number(payload.milestoneNumber || payload.milestone || 1);
const milestoneTitle = String(payload.milestoneTitle || `Milestone ${milestoneNumber}`).trim();
const clientLegalName = String(payload.clientLegalName || payload.clientName || 'Valued Client').trim();
const clientEmail = String(payload.clientEmail || payload.email || '').trim().toLowerCase();
const clientGstin = String(payload.clientGstin || payload.gstin || '').trim().toUpperCase();
const currency = String(payload.currency || 'INR').trim().toUpperCase();
const baseAmount = Number(payload.baseAmount || payload.amount || 0);
const country = String(payload.country || 'IN').trim().toUpperCase();

const isDomestic = country === 'IN' || currency === 'INR';
let taxRate = 0;
let taxType = 'EXPORT_ZERO_RATED';
let taxAmount = 0;
let cgst = 0;
let sgst = 0;
let igst = 0;

if (isDomestic) {
  taxRate = 0.18;
  taxAmount = Math.round(baseAmount * taxRate * 100) / 100;
  const isInterstate = clientGstin && !clientGstin.startsWith('33'); // 33 is Tamil Nadu State Code for LIT
  if (isInterstate) {
    taxType = 'IGST_18';
    igst = taxAmount;
  } else {
    taxType = 'CGST_SGST_18';
    cgst = Math.round((taxAmount / 2) * 100) / 100;
    sgst = Math.round((taxAmount / 2) * 100) / 100;
  }
}

const totalAmount = Math.round((baseAmount + taxAmount) * 100) / 100;
const year = new Date().getFullYear();
const seq = Math.floor(1000 + Math.random() * 9000);
const invoiceNumber = `LIT-INV-${year}-${seq}`;
const issueDate = new Date().toISOString();
const dueDate = new Date(Date.now() + 15 * 86400 * 1000).toISOString();

return [{
  json: {
    eventId: item.eventId,
    verified: item.verified,
    invoice: {
      invoiceNumber,
      projectId,
      milestoneNumber,
      milestoneTitle,
      clientLegalName,
      clientEmail,
      clientGstin: clientGstin || 'UNREGISTERED',
      currency,
      baseAmount,
      taxRate,
      taxType,
      cgst,
      sgst,
      igst,
      taxAmount,
      totalAmount,
      issueDate,
      dueDate,
      paymentTerms: 'Net 15 Days',
      beneficiaryName: 'Logic Intelligence Technologies',
      lutReference: isDomestic ? null : 'LUT-ARN-AD330224001928K'
    }
  }
}];

const item = $input.first().json;
const inv = item.invoice;

const notificationPayload = {
  recipientEmail: inv.clientEmail,
  recipientName: inv.clientLegalName,
  subject: `Invoice ${inv.invoiceNumber} for ${inv.milestoneTitle} — Logic Intelligence Technologies`,
  invoiceNumber: inv.invoiceNumber,
  totalAmountFormatted: `${inv.currency} ${inv.totalAmount.toLocaleString('en-IN')}`,
  dueDate: inv.dueDate,
  paymentPortalPath: `/portal/billing/invoices/${inv.invoiceNumber}`,
  paymentGateway: inv.currency === 'INR' ? 'Razorpay' : 'Stripe',
  wireTransferEligible: inv.totalAmount >= 50000
};

return [{
  json: {
    eventId: item.eventId,
    status: 'milestone_invoice_created',
    detail: {
      invoice: inv,
      notification: notificationPayload,
      generatedAt: new Date().toISOString()
    }
  }
}];

const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) { throw new Error('N8N_WEBHOOK_SECRET is not set'); }
const item = $input.first();
const eventId = item.json.eventId;
const ts = String(Math.floor(Date.now() / 1000));
const payload = {
  eventId,
  status: item.json.status || 'processed',
  detail: item.json.detail || {}
};
const rawBody = JSON.stringify(payload);
const mac = crypto.createHmac('sha256', secret).update(ts + '.' + eventId + '.' + rawBody).digest('hex');
return [{ json: { eventId, status: payload.status, rawBody, timestamp: ts, signature: 'v1=' + mac } }];
